// Maps (`maps.tenshu.app`) — a Tenshu app on its own origin (ADR 0020), on the shared app
// preset (`@tenshu/app-kit`, web-app-suite.md F3): Vite + Vitest + Tailwind, the dev server's
// `fs.allow` and the served `manifest.webmanifest`. Generated by scripts/new-web-app.sh.
//
// ⚠ Imported by its file path, not `@tenshu/app-kit/vite`: Node loads this config and refuses to
// strip types from a `.ts` it resolved through `node_modules`. The same holds for the map-kit's
// glyphs plugin (docs/how-to/new-web-app.md §2b).
import { mergeConfig } from 'vite'
import { tenshuAppConfig } from '../app-kit/src/vite.ts'
import { tenshuMapGlyphs } from '../map-kit/src/vite.ts'

// ⚠ No `chunkSizeWarningLimit` override: this bundle must NOT contain the Kotlin runtime, so Vite's
// default 500 kB warning is the tripwire for a stray SDK value import. MapLibre is its own lazily
// loaded chunk (`sdkBoundary.test.ts`), and over the limit on its own — that warning is expected.
export default mergeConfig(
  tenshuAppConfig({
    // The apex registry entry (`web/apex/src/apps/registry/apps/maps.ts`) names the same port.
    port: 5179,
    manifest: {
      id: 'maps',
      name: 'Maps',
      description: 'Your places, end-to-end encrypted.',
      // docs/web/architecture.md §6. Display/declaration data; the apex allowlist is the enforcement.
      semanticPermissions: [
        {
          id: 'tenshu/maps/service',
          humanDescription: 'Read your places and their visits; rename places; draw them on the map',
          scope: ['/'],
        },
      ],
    },
  }),
  // `/glyphs/<fontstack>/<range>.pbf` from this origin — the default `glyphsBase` `<TenshuMap>` uses.
  { plugins: [tenshuMapGlyphs()] },
)
